/**
 * Typography (DESIGN 11). Interface: Inter ("OMS Sans", public/fonts, posta à
 * cabeça da pilha de sistema do react-native-web por um remendo) na web e no
 * desktop; no iOS e no Android a letra do sistema (SF Pro, Roboto). Sem
 * serifa (o dono escolheu o idioma do Apple Music, 2026-11-04). Display faces are bundled:
 * OMS Wide (our own ultra-wide black, weight 900; generated by
 * scripts/generate-oms-wide.py - it replaced a Druk Wide TRIAL that could not
 * be redistributed). Cantarell saiu a 2026-11-04: carregava 112 KB em cada
 * arranque e nenhum ecrã a usava.
 */
import { Platform } from "react-native";
import * as Font from "expo-font";

export const FONT_OMS_WIDE = "OMSWide";

/**
 * A letra da interface escrita por extenso, para o que NÃO passa pelo Text do
 * react-native-web (as etiquetas da barra de tabs do React Navigation usam a
 * pilha de sistema dele, que no Linux é a Ubuntu/DejaVu).
 */
export const FONT_SANS = Platform.select({
  web: '"OMS Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  default: undefined,
}) as string | undefined;


/** Body: platform default (SF Pro / Roboto). */
export const FONT_BODY = Platform.select({ ios: "System", default: "sans-serif" }) as string;

let loadPromise: Promise<void> | null = null;

/** Idempotent; kicked off by the ThemeProvider. Failures are non-fatal. */
export const loadFonts = (): Promise<void> => {
  if (!loadPromise) {
    loadPromise = Font.loadAsync({
      [FONT_OMS_WIDE]: require("../../assets/fonts/OMSWide-Regular.ttf") as number,
    }).catch(() => {
      // Missing display fonts degrade to the system face.
    });
  }
  return loadPromise;
};

export const fontsLoaded = (): boolean => Font.isLoaded(FONT_OMS_WIDE);

// ---------------------------------------------------------------------------
// Text style conventions (SPEC design language). Consumed by WP4's UI kit.
// ---------------------------------------------------------------------------

export const typeScale = {
  /** Hero titles: huge black-weight. */
  heroTitle: { fontSize: 34, fontWeight: "900" as const, letterSpacing: -0.5 },
  /** Section headers: 2xl bold tight. */
  sectionHeader: { fontSize: 24, fontWeight: "700" as const, letterSpacing: -0.4 },
  /** Kind labels above hero titles: tiny uppercase. */
  kindLabel: {
    fontSize: 12,
    fontWeight: "600" as const,
    textTransform: "uppercase" as const,
    letterSpacing: 0.6,
  },
  /** Tile titles + subtitles. */
  tileTitle: { fontSize: 14, fontWeight: "600" as const },
  tileSubtitle: { fontSize: 12 },
  /** Time labels: tabular numerals. */
  timeLabel: { fontSize: 11, fontVariant: ["tabular-nums" as const] },
} as const;
